"""CampusConnect end-to-end API checks: posting rules, moderation, clubs, events, RSVP/waitlist, check-in, lost & found, guards.
Usage: python3 tests/e2e_lifecycle.py   (needs the seeded database; env BASE / MYSQL / DB_NAME as in lib.py)
The test creates rows prefixed "E2E" and removes them at the start of every run, so it can be repeated."""
import time, datetime as dt
from lib import *

D = lambda days, hm: (dt.date.today() + dt.timedelta(days=days)).isoformat() + ' ' + hm
uid = lambda name: int(val(f"SELECT id FROM users WHERE username='{name}'"))

# ---- clean previous runs
sql("DELETE FROM events WHERE title LIKE 'E2E%'"); sql("DELETE FROM posts WHERE body LIKE 'E2E%'"); sql("DELETE FROM lost_items WHERE title LIKE 'E2E%'")
sql("UPDATE posts SET is_pinned = 0 WHERE title LIKE 'E2E%'")
sql("DELETE FROM club_members WHERE user_id IN (SELECT id FROM users WHERE username IN ('student50','student51','student52')) AND club_id IN (2,3,6,9)")

adm = Client('admin', 'admin123'); lec = Client('lecturer1', 'staff123'); lec2 = Client('lecturer2', 'staff123')
st = {n: Client(f'student{n}', 'student123') for n in (1, 2, 3, 4, 5, 40, 50, 51, 52, 53, 54, 55, 56)}
check('logins work', all(c.ok for c in [adm, lec, lec2, *st.values()]))
check('bad password rejected', not Client('student1', 'nope').ok)

print('== guards')
r = st[1].s.get(BASE + '/admin/users', allow_redirects=False); check('student blocked from admin pages', r.status_code in (302, 403) and 'admin' not in r.headers.get('Location', ''), r.status_code)
check('student blocked from admin api', st[1].get('admin/users-api', action='list').status_code == 403)
check('anonymous API is 401', requests.get(BASE + '/feed/api?action=list').status_code in (401, 403))
check('POST without CSRF is 403', st[1].post('feed/api', csrf=False, action='create', type='Discussion', body='E2E nocsrf').status_code == 403)

print('== posts')
r = st[1].post('feed/api', action='create', type='Discussion', body='E2E hello campus'); check('student can post', r.json().get('success'), r.text)
pid = r.json().get('id')
r = st[1].post('feed/api', action='create', type='Discussion', body='E2E too fast'); check('10 s cooldown enforced', r.status_code == 422 and 'wait' in r.json()['message'].lower(), r.text)
check('empty post rejected', st[2].post('feed/api', action='create', type='Discussion', body='   ').status_code == 422)
check('too long post rejected', st[2].post('feed/api', action='create', type='Discussion', body='x' * 2001).status_code == 422)
check('student cannot announce', st[2].post('feed/api', action='create', type='Announcement', title='E2E x', body='E2E x').status_code == 422)
r = lec.post('feed/api', action='create', type='Announcement', body='E2E no title'); check('announcement needs title', r.status_code == 422, r.text)
r = lec.post('feed/api', action='create', type='Announcement', title='E2E Exam timetable', body='E2E timetable released', programme_id=1); check('staff announcement for one programme', r.json().get('success'), r.text); aid = r.json().get('id')
vis = lambda c, i: any(p['id'] == i for p in c.get('feed/api', action='list', q='E2E').json().get('posts', []))
check('HNDIT student sees HNDIT announcement', vis(st[2], aid)); check('HNDA student does not', not vis(st[4], aid)); check('student1 (other programme) does not', not vis(st[1], aid))
r = st[2].post('feed/api', action='create', type='Discussion', body='E2E for hndit', programme_id=1); check('student cannot target an audience', r.status_code == 422, r.text)
check('student cannot pin', st[1].post('feed/api', action='pin', id=aid).status_code == 403)
check('staff can pin', lec.post('feed/api', action='pin', id=aid).json().get('success'))
r = st[1].post('feed/api', action='like', id=pid); check('like', r.json().get('liked') == 0 or r.json().get('success'), r.text)
r = st[2].post('feed/api', action='like', id=pid); check('second user like counts', r.json().get('likes') == 2, r.text)
r = st[2].post('feed/api', action='like', id=pid); check('unlike toggles', r.json().get('likes') == 1, r.text)
r = st[2].post('feed/api', action='comment', post_id=pid, body='E2E nice one'); check('comment', r.json().get('success'), r.text); cid = r.json()['comment']['id'] if r.json().get('comment') else 0
check('empty comment rejected', st[2].post('feed/api', action='comment', post_id=pid, body='').status_code == 422)
check('others cannot delete my post', st[2].post('feed/api', action='delete', id=pid).status_code == 403)
check('notification sent to post author', int(val(f"SELECT COUNT(*) FROM notifications WHERE user_id={uid('student1')} AND type='comment' AND created_at > NOW() - INTERVAL 1 MINUTE")) >= 1)

print('== reports & auto-hide')
check('cannot report own post', st[1].post('feed/api', action='report', entity='post', id=pid, reason='Spam').status_code == 409)
check('invalid reason rejected', st[3].post('feed/api', action='report', entity='post', id=pid, reason='Boring').status_code == 409)
for n in (3, 4): check(f'report #{n-2}', st[n].post('feed/api', action='report', entity='post', id=pid, reason='Spam').json().get('success'))
check('duplicate report rejected', st[3].post('feed/api', action='report', entity='post', id=pid, reason='Spam').status_code == 409)
check('still visible after 2 reports', vis(st[2], pid))
check('third report', st[5].post('feed/api', action='report', entity='post', id=pid, reason='Harassment').json().get('success'))
check('auto-hidden after 3 reports', val(f"SELECT status FROM posts WHERE id={pid}") == 'Hidden')
check('hidden post invisible to students', not vis(st[2], pid))
check('moderation queue lists it (admin)', any(int(x['entity_id']) == pid for x in adm.get('admin/moderation-api').json().get('data', [])))
check('student cannot use moderation api', st[2].post('admin/moderation-api', action='resolve', entity='post', id=pid, decision='dismiss').status_code == 403)
check('admin dismisses -> restored', adm.post('admin/moderation-api', action='resolve', entity='post', id=pid, decision='dismiss').json().get('success') and val(f"SELECT status FROM posts WHERE id={pid}") == 'Published')
check('admin can hide a post', adm.post('feed/api', action='hide', id=pid).json().get('success') and val(f"SELECT status FROM posts WHERE id={pid}") == 'Hidden')
adm.post('feed/api', action='unhide', id=pid)
print('  pin limit')
sql("UPDATE posts SET is_pinned = 0")
ids = []
for i in range(4):
    r = lec2.post('feed/api', action='create', type='Announcement', title=f'E2E pin {i}', body='E2E pinnable'); ids.append(r.json().get('id')); time.sleep(10.2) if i < 3 else None
res = [lec.post('feed/api', action='pin', id=i).status_code for i in ids]; check('only 3 posts can be pinned', res == [200, 200, 200, 403], res)
sql("UPDATE posts SET is_pinned = 0")

print('== clubs')
check('student joins an open club', st[50].post('clubs/api', action='join', id=3).json().get('status') == 'Active')
check('cannot join twice', st[50].post('clubs/api', action='join', id=3).status_code == 409)
r = st[50].post('clubs/api', action='join', id=2); check('approval club -> Pending', r.json().get('status') == 'Pending', r.text)
check('non-manager cannot approve', st[51].post('clubs/api', action='decide', id=2, user_id=uid('student50'), approve=1).status_code == 409)
mgr = Client(val("SELECT username FROM users WHERE id=53"), 'student123')
check('president approves request', mgr.post('clubs/api', action='decide', id=2, user_id=uid('student50'), approve=1).json().get('success'))
check('now active', val(f"SELECT status FROM club_members WHERE club_id=2 AND user_id={uid('student50')}") == 'Active')
check('declined request is removed', st[51].post('clubs/api', action='join', id=2).json().get('status') == 'Pending' and mgr.post('clubs/api', action='decide', id=2, user_id=uid('student51'), approve=0).json().get('success') and val(f"SELECT COUNT(*) FROM club_members WHERE club_id=2 AND user_id={uid('student51')}") == '0')
check('president cannot leave', Client(val('SELECT username FROM users WHERE id=10'), 'student123').post('clubs/api', action='leave', id=3).status_code == 409)
check('staff cannot join clubs', lec.post('clubs/api', action='join', id=1).status_code == 409)
check('officer promotion by president', mgr.post('clubs/api', action='role', id=2, user_id=uid('student50'), role='Officer').json().get('success'))
check('only one president after handover', (mgr.post('clubs/api', action='role', id=2, user_id=uid('student50'), role='President').json().get('success')) and val("SELECT COUNT(*) FROM club_members WHERE club_id=2 AND role='President'") == '1')
check('old president demoted to officer', val("SELECT role FROM club_members WHERE club_id=2 AND user_id=53") == 'Officer')
check('leave works', st[50].post('clubs/api', action='leave', id=3).json().get('success'))
# member cap
sql("DELETE FROM club_members WHERE user_id=" + str(uid('student55'))); 
for c in range(1, 9): sql(f"INSERT INTO club_members (club_id,user_id,role,status) VALUES ({c},{uid('student55')},'Member','Active')")
check('max 8 clubs enforced', st[55].post('clubs/api', action='join', id=9).status_code == 409 and st[55].post('clubs/api', action='join', id=10).status_code == 409)
sql("DELETE FROM club_members WHERE user_id=" + str(uid('student55')))
sql("DELETE FROM club_members WHERE user_id=" + str(uid('student50')) + " AND club_id=2")
sql("UPDATE club_members SET role='President' WHERE club_id=2 AND user_id=53")

print('== events')
base = dict(action='save', title='E2E Open Day', category='Academic', venue='Main Auditorium', starts_at=D(120, '09:00'), ends_at=D(120, '11:00'), capacity=2, description='x')
r = lec.post('events/api', **base); check('staff event auto-approved', r.json().get('success') and val(f"SELECT status FROM events WHERE id={r.json()['id']}") == 'Approved', r.text); e1 = r.json().get('id')
r = st[1].post('events/api', **{**base, 'title': 'E2E Clash', 'starts_at': D(120, '10:00'), 'ends_at': D(120, '12:00')}); check('venue clash blocked', r.status_code == 422 and 'booked' in r.json()['message'], r.text)
bad = lambda **k: st[1].post('events/api', **{**base, 'title': 'E2E Bad', 'venue': 'Library Hall', **k}).status_code == 422
check('past start rejected', bad(starts_at=D(-1, '09:00'), ends_at=D(-1, '10:00')))
check('less than 30 min lead rejected', bad(starts_at=(dt.datetime.now() + dt.timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M'), ends_at=(dt.datetime.now() + dt.timedelta(minutes=70)).strftime('%Y-%m-%d %H:%M')))
check('end before start rejected', bad(starts_at=D(121, '10:00'), ends_at=D(121, '09:00')))
check('multi-day rejected', bad(starts_at=D(121, '10:00'), ends_at=D(122, '10:00')))
check('ends after 20:00 rejected', bad(starts_at=D(121, '18:00'), ends_at=D(121, '21:00')))
check('over 12 hours rejected', bad(starts_at=D(121, '07:00'), ends_at=D(121, '19:30')))
check('more than 180 days ahead rejected', bad(starts_at=D(200, '09:00'), ends_at=D(200, '10:00')))
check('unknown venue rejected', bad(venue='Rooftop'))
check('capacity 0 rejected', bad(capacity=0))
r = st[1].post('events/api', **{**base, 'title': 'E2E Student Event', 'venue': 'Library Hall', 'starts_at': D(121, '09:00'), 'ends_at': D(121, '11:00')}); check('student event is Pending', r.json().get('success') and val(f"SELECT status FROM events WHERE id={r.json()['id']}") == 'Pending', r.text); e2 = r.json().get('id')
check('pending event hidden from others', st[2].get('events/api', action='get', id=e2).status_code == 404)
check('organiser can see own pending event', st[1].get('events/api', action='get', id=e2).status_code == 200)
check('cannot RSVP to pending event', st[2].post('events/api', action='rsvp', id=e2, status='Going').status_code == 409)
check('student cannot approve', st[1].post('events/api', action='decide', id=e2, approve=1).status_code == 409)
check('reject needs a reason', adm.post('events/api', action='decide', id=e2, approve=0, note='no').status_code == 409)
check('admin approves', adm.post('events/api', action='decide', id=e2, approve=1).json().get('success') and val(f"SELECT status FROM events WHERE id={e2}") == 'Approved')
check('decided event cannot be decided again', adm.post('events/api', action='decide', id=e2, approve=1).status_code == 409)
r = st[1].post('events/api', **{**base, 'title': 'E2E Student Event 2', 'venue': 'Seminar Room'}); e3 = r.json().get('id')
check('admin rejects with reason', adm.post('events/api', action='decide', id=e3, approve=0, note='Clashes with exams').json().get('success') and val(f"SELECT status FROM events WHERE id={e3}") == 'Rejected')
r = st[1].post('events/api', **{**base, 'id': e2, 'venue': 'Library Hall', 'title': 'E2E Student Event', 'starts_at': D(121, '13:00'), 'ends_at': D(121, '15:00')}); check('rescheduling approved student event sends it back to Pending', r.json().get('success') and val(f"SELECT status FROM events WHERE id={e2}") == 'Pending', r.text)
adm.post('events/api', action='decide', id=e2, approve=1)
print('  rsvp, capacity, waitlist')
check('A going', st[1].post('events/api', action='rsvp', id=e1, status='Going').json().get('status') == 'Going')
check('B going', st[2].post('events/api', action='rsvp', id=e1, status='Going').json().get('status') == 'Going')
check('C waitlisted (capacity 2)', st[3].post('events/api', action='rsvp', id=e1, status='Going').json().get('status') == 'Waitlist')
check('D waitlisted', st[4].post('events/api', action='rsvp', id=e1, status='Going').json().get('status') == 'Waitlist')
time.sleep(1.1)
check('duplicate RSVP rejected', st[1].post('events/api', action='rsvp', id=e1, status='Going').status_code == 409)
check('interested allowed without seat', st[5].post('events/api', action='rsvp', id=e1, status='Interested').json().get('status') == 'Interested')
# overlap: A is going to e1 (120d 09-11). Another approved event overlapping
r = lec.post('events/api', **{**base, 'title': 'E2E Overlap', 'venue': 'Lecture Hall A', 'starts_at': D(120, '10:00'), 'ends_at': D(120, '12:00'), 'capacity': ''}); e4 = r.json().get('id')
check('cannot be Going to two overlapping events', st[1].post('events/api', action='rsvp', id=e4, status='Going').status_code == 409)
check('but can be Interested', st[1].post('events/api', action='rsvp', id=e4, status='Interested').json().get('success'))
check('A cancels RSVP', st[1].post('events/api', action='cancel_rsvp', id=e1).json().get('success'))
check('oldest waitlisted (C) promoted', val(f"SELECT status FROM event_rsvps WHERE event_id={e1} AND user_id={uid('student3')}") == 'Going' and val(f"SELECT status FROM event_rsvps WHERE event_id={e1} AND user_id={uid('student4')}") == 'Waitlist')
check('promotion notification sent', int(val(f"SELECT COUNT(*) FROM notifications WHERE user_id={uid('student3')} AND message LIKE '%seat opened%'")) >= 1)
# promotion skips clashing waitlisted user
sql(f"INSERT INTO event_rsvps (event_id,user_id,status) VALUES ({e4},{uid('student4')},'Going') ON DUPLICATE KEY UPDATE status='Going'")
check('B cancels, D skipped because of clash', st[2].post('events/api', action='cancel_rsvp', id=e1).json().get('success') and val(f"SELECT status FROM event_rsvps WHERE event_id={e1} AND user_id={uid('student4')}") == 'Waitlist')
check('cancel without RSVP rejected', st[2].post('events/api', action='cancel_rsvp', id=e1).status_code == 409)
check('capacity cannot drop below going count', lec.post('events/api', **{**base, 'id': e1, 'capacity': 0}).status_code == 422)
r = lec.post('events/api', **{**base, 'id': e1, 'capacity': 1}); check('capacity 1 with 1 going is OK', r.json().get('success'), r.text)

print('== check-in')
check('guest list hidden from attendees', st[3].get('events/api', action='attendees', id=e1).status_code == 403)
check('code hidden from attendees', st[3].get('events/api', action='code', id=e1).status_code == 403)
check('guest list visible to organiser', len(lec.get('events/api', action='attendees', id=e1).json()['data']) >= 2)
check('check-in before window rejected', st[3].post('events/api', action='checkin', id=e1, code='123456').status_code == 409)
check('organiser check-in before window rejected', lec.post('events/api', action='checkin_member', id=e1, user_id=uid('student3'), **{'in': 1}).status_code == 409)
# open the window by moving the event to "now"
code = lec.get('events/api', action='code', id=e1).json()['code']
sql(f"UPDATE events SET starts_at = NOW() - INTERVAL 10 MINUTE, ends_at = NOW() + INTERVAL 90 MINUTE WHERE id={e1}")
check('wrong code rejected', st[3].post('events/api', action='checkin', id=e1, code='000000').status_code == 409)
check('waitlisted cannot check in', st[4].post('events/api', action='checkin', id=e1, code=code).status_code == 409)
check('right code checks in', st[3].post('events/api', action='checkin', id=e1, code=code).json().get('success') and val(f"SELECT checked_in_at IS NOT NULL FROM event_rsvps WHERE event_id={e1} AND user_id={uid('student3')}") == '1')
check('double check-in rejected', st[3].post('events/api', action='checkin', id=e1, code=code).status_code == 409)
check('checked-in user cannot cancel RSVP', st[3].post('events/api', action='cancel_rsvp', id=e1).status_code == 409)
for i in range(5): st[5].post('events/api', action='checkin', id=e1, code='111111')
check('5 wrong tries lock the attendee out', st[5].post('events/api', action='checkin', id=e1, code=code).status_code == 409)
check('organiser can undo a check-in', lec.post('events/api', action='checkin_member', id=e1, user_id=uid('student3'), **{'in': 0}).json().get('success') and val(f"SELECT checked_in_at IS NULL FROM event_rsvps WHERE event_id={e1} AND user_id={uid('student3')}") == '1')
check('other staff cannot check people in', lec2.post('events/api', action='checkin_member', id=e1, user_id=uid('student3'), **{'in': 1}).status_code == 409)
sql(f"UPDATE events SET starts_at = NOW() - INTERVAL 3 HOUR, ends_at = NOW() - INTERVAL 2 HOUR WHERE id={e1}")
check('check-in closes 1 hour after the end', st[3].post('events/api', action='checkin', id=e1, code=code).status_code == 409)
check('past event cannot be edited', lec.post('events/api', **{**base, 'id': e1}).status_code == 422)
check('past event cannot be cancelled', lec.post('events/api', action='cancel', id=e1, reason='too late now').status_code == 409)

print('== cancel event')
check('cancel needs a reason', lec.post('events/api', action='cancel', id=e4, reason='x').status_code == 409)
check('non-manager cannot cancel', st[3].post('events/api', action='cancel', id=e4, reason='because I said so').status_code == 409)
check('organiser cancels', lec.post('events/api', action='cancel', id=e4, reason='Speaker unavailable').json().get('success') and val(f"SELECT status FROM events WHERE id={e4}") == 'Cancelled')
check('attendees notified of cancellation', int(val(f"SELECT COUNT(*) FROM notifications WHERE user_id={uid('student4')} AND message LIKE '%cancelled%' AND created_at > NOW() - INTERVAL 1 MINUTE")) >= 1)
check('cannot RSVP to cancelled event', st[2].post('events/api', action='rsvp', id=e4, status='Going').status_code == 409)

print('== lost & found')
r = st[1].post('lost-found/api', action='create', kind='Lost', title='E2E Blue bottle', location='Library', happened_on=dt.date.today().isoformat(), description='dented'); check('post lost item', r.json().get('success'), r.text); l1 = r.json().get('id')
check('future date rejected', st[1].post('lost-found/api', action='create', kind='Lost', title='E2E X', location='Lab', happened_on=(dt.date.today() + dt.timedelta(days=2)).isoformat()).status_code == 422)
check('date older than 60 days rejected', st[1].post('lost-found/api', action='create', kind='Found', title='E2E X', location='Lab', happened_on=(dt.date.today() - dt.timedelta(days=90)).isoformat()).status_code == 422)
check('bad kind rejected', st[1].post('lost-found/api', action='create', kind='Stolen', title='E2E X', location='Lab', happened_on=dt.date.today().isoformat()).status_code == 422)
check('cannot claim own item', st[1].post('lost-found/api', action='claim', id=l1, note='this is totally mine okay').status_code == 409)
check('claim note needs 10+ characters', st[2].post('lost-found/api', action='claim', id=l1, note='short').status_code == 409)
check('claim', st[2].post('lost-found/api', action='claim', id=l1, note='Found it near the library entrance at lunch').json().get('success') and val(f"SELECT status FROM lost_items WHERE id={l1}") == 'Claim Pending')
check('second claim rejected', st[3].post('lost-found/api', action='claim', id=l1, note='I also found it somewhere else').status_code == 409)
