check('non-poster cannot decide', st[3].post('lost-found/api', action='confirm', id=l1).status_code == 409)
check('poster rejects -> Open again', st[1].post('lost-found/api', action='reject', id=l1).json().get('success') and val(f"SELECT status FROM lost_items WHERE id={l1}") == 'Open' and val(f"SELECT claimant_id IS NULL FROM lost_items WHERE id={l1}") == '1')
st[3].post('lost-found/api', action='claim', id=l1, note='Picked it up from the canteen table')
check('poster confirms -> Resolved', st[1].post('lost-found/api', action='confirm', id=l1).json().get('success') and val(f"SELECT status FROM lost_items WHERE id={l1}") == 'Resolved')
it = {i['id']: i for i in st[1].get('lost-found/api', action='list', status='Resolved').json()['data']}[l1]
check('poster sees claimant phone after resolution', 'claimant_phone' in it)
check('only owner/admin can delete', st[2].post('lost-found/api', action='delete', id=l1).status_code == 403 and adm.post('lost-found/api', action='delete', id=l1).json().get('success'))

